<?php require_once 'config/functions.php';require_login();$uid=user_id();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['add'])){$title=trim($_POST['title']??'');$target=(float)($_POST['target']??0);if($title&&$target>0)$pdo->prepare('INSERT INTO goals(user_id,title,target,current_value,deadline) VALUES(?,?,?,0,?)')->execute([$uid,$title,$target,$_POST['deadline']?:null]);flash('Goal created!');}if(isset($_POST['update'])){$pdo->prepare('UPDATE goals SET current_value=? WHERE id=? AND user_id=?')->execute([(float)$_POST['current'],(int)$_POST['goal_id'],$uid]);flash('Progress updated.');}if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM goals WHERE id=? AND user_id=?')->execute([(int)$_POST['delete'],$uid]);flash('Goal deleted.');}redirect('goals.php');}$q=$pdo->prepare('SELECT * FROM goals WHERE user_id=? ORDER BY id DESC');$q->execute([$uid]);$goals=$q->fetchAll();page_header('Goals & Savings');?><div class="card"><h3>Create a goal</h3><form method="post" class="grid grid-3"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="field"><label>Goal name</label><input name="title" placeholder="Save for a trip" required></div><div class="field"><label>Target amount</label><input name="target" type="number" step="0.01" min="0.01" required></div><div class="field"><label>Target date (optional)</label><input name="deadline" type="date"></div><div><button name="add">Create Goal</button></div></form></div><div class="grid grid-2" style="margin-top:18px"><?php if(!$goals):?><div class="card empty">No goals yet. Set one meaningful goal for yourself.</div><?php else:foreach($goals as $g):$percent=min(100,100*$g['current_value']/$g['target']);?><div class="card"><h3>☆ <?=h($g['title'])?></h3><div class="stat"><?=number_format($g['current_value'],2)?> / <?=number_format($g['target'],2)?></div><div class="progress"><div style="width:<?=$percent?>%"></div></div><p class="small"><?=round($percent)?>% complete · <?=h($g['deadline']?:'No deadline')?></p><form method="post" class="row"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="goal_id" value="<?=$g['id']?>"><input name="current" type="number" step="0.01" min="0" max="<?=$g['target']?>" value="<?=$g['current_value']?>" style="width:130px"><button name="update">Update</button><button class="btn danger" name="delete" value="<?=$g['id']?>" data-confirm="Delete this goal?">Delete</button></form></div><?php endforeach;endif;?></div><?php page_footer();
